package com.kisa.tmaprouteprobe;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.view.inputmethod.EditorInfo;import android.webkit.WebView;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.*;import java.io.*;import java.nio.file.*;
/** Runs the user's magnifier -> input -> native result -> Naver flow. */
public final class KisaActualSearchRunner extends Instrumentation {
 String hostMode="safe";ClassLoader cl;Activity navi;volatile Activity current;JSONObject report=new JSONObject();File dir;String query="수학의 힘 신 검단캠퍼스";
 void check(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}
 View tag(View v,String text){if(text.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=tag(((ViewGroup)v).getChildAt(i),text);if(r!=null)return r;}return null;}
 AccessibilityNodeInfo text(AccessibilityNodeInfo v,String wanted){if(v==null)return null;if(wanted.contentEquals(v.getText()==null?"":v.getText()))return v;for(int i=0;i<v.getChildCount();i++){AccessibilityNodeInfo found=text(v.getChild(i),wanted);if(found!=null)return found;}return null;}
 AccessibilityNodeInfo contains(AccessibilityNodeInfo v,String wanted){if(v==null)return null;String value=v.getText()==null?"":v.getText().toString();if(value.contains(wanted))return v;for(int i=0;i<v.getChildCount();i++){AccessibilityNodeInfo found=contains(v.getChild(i),wanted);if(found!=null)return found;}return null;}
 void shot(String name)throws Exception{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(dir,name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 void tree(View view,JSONArray out)throws Exception{if(view instanceof WebView)out.put(new JSONObject().put("web",String.valueOf(((WebView)view).getUrl())));if(view.getTag()!=null)out.put(new JSONObject().put("tag",String.valueOf(view.getTag())).put("shown",view.isShown()));if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)tree(((ViewGroup)view).getChildAt(i),out);}
 void startRoute(Context c)throws Exception{
  JSONObject goal=new JSONObject().put("name","수학의힘 신검단캠퍼스학원").put("lat",37.6034634).put("lon",126.6981604);
  Method destination=cl.loadClass("com.kisa.naverroute.NaverPlaceSearch").getDeclaredMethod("destinationIntent",Context.class,JSONObject.class);destination.setAccessible(true);
  Activity preview=startActivitySync(((Intent)destination.invoke(null,c,goal)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  Object vm=call(preview,"p0",new Class<?>[]{}),counter=get(vm,"u0"),session=null,card=null;Class<?> bridge=cl.loadClass("com.kisa.naverroute.PreviewBridge");long until=SystemClock.elapsedRealtime()+45000;
  while(SystemClock.elapsedRealtime()<until){final Object ctr=counter;main(()->ctr.getClass().getMethod("setValue",Object.class).invoke(ctr,false));session=((Map<?,?>)get(bridge,"SESSIONS")).get(vm);if(session!=null&&Boolean.TRUE.equals(get(session,"choiceDone"))){for(Object item:(List<?>)call(get(vm,"j0"),"getValue",new Class<?>[]{}))if("Traffic_Recommend".equals(String.valueOf(call(item,"getRoutePlanType",new Class<?>[]{}))))card=item;if(card!=null)break;}Thread.sleep(200);}
  check(card!=null,"Native route not ready");Object fragment=((java.lang.ref.Reference<?>)get(session,"fragment")).get();Class<?> callback=cl.loadClass("com.skt.tmap.mvp.fragment.TmapRoutePreviewFragment$e");Object cb=callback.getConstructor(fragment.getClass()).newInstance(fragment);
  List<?> ordered=(List<?>)call(get(get(vm,"k0"),"Z"),"getValue",new Class<?>[]{});int index=-1;for(int i=0;i<ordered.size();i++)if(call(ordered.get(i),"getRoutePlanType",new Class<?>[]{})==call(card,"getRoutePlanType",new Class<?>[]{}))index=i;
  final Object chosen=card;final int at=index;main(()->callback.getMethod("e",int.class,chosen.getClass()).invoke(cb,at,chosen));Thread.sleep(300);
  ActivityMonitor monitor=addMonitor("com.skt.tmap.activity.TmapNaviActivity",null,false);main(()->{View startButton=preview.findViewById(preview.getResources().getIdentifier("route_preview_drive_button","id",preview.getPackageName()));check(startButton!=null&&startButton.isShown()&&startButton.performClick(),"Native start guidance button missing");});navi=waitForMonitorWithTimeout(monitor,10000);check(navi!=null,"Route guidance host missing");Thread.sleep(4000);main(()->c.startActivity(c.getPackageManager().getLaunchIntentForPackage(c.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));Thread.sleep(1000);
  Object manager=cl.loadClass("com.skt.tmap.engine.navigation.NavigationManager").getMethod("getInstance").invoke(null);report.put("native_drive_mode",String.valueOf(call(manager,"getDriveMode",new Class<?>[]{})));
 }
 android.view.accessibility.AccessibilityNodeInfo findText(android.view.accessibility.AccessibilityNodeInfo node,String text){if(node==null)return null;if(text.replace(" ","").equals(node.getText()==null?"":node.getText().toString().replace(" ",""))||text.replace(" ","").equals(node.getContentDescription()==null?"":node.getContentDescription().toString().replace(" ","")))return node;for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo hit=findText(node.getChild(i),text);if(hit!=null)return hit;}return null;}
 void main(Throwing action){runOnMainSync(()->{try{action.run();}catch(Exception e){throw new RuntimeException(e);}});}interface Throwing{void run()throws Exception;}
 static Object get(Object o,String n)throws Exception{Field f=o instanceof Class?((Class<?>)o).getDeclaredField(n):o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o instanceof Class?null:o);}
 static Object call(Object o,String n,Class<?>[] t,Object...args)throws Exception{Method m=o.getClass().getMethod(n,t);m.setAccessible(true);return m.invoke(o,args);}
 public void onCreate(Bundle b){super.onCreate(b);hostMode=b.getString("host","safe");start();}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();cl=c.getClassLoader();android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS;getUiAutomation().setServiceInfo(info);dir=new File(c.getExternalFilesDir(null),"kisa_actual_search_probe");dir.mkdirs();Application application=(Application)c.getApplicationContext();application.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){current=a;}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
  startActivitySync(c.getPackageManager().getLaunchIntentForPackage(c.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(3000);check(current!=null,"Home missing");Activity home=current;runOnMainSync(()->{try{c.getClassLoader().loadClass("com.kisa.naverroute.HomeIdleBridge").getMethod("pause",Activity.class).invoke(null,home);}catch(Exception e){throw new RuntimeException(e);}});if(hostMode.equals("route")){startRoute(c);}else{runOnMainSync(()->home.findViewById(home.getResources().getIdentifier("button_safety_driving","id",home.getPackageName())).performClick());Thread.sleep(2300);}Activity navi=current;report.put("host",hostMode);report.put("safe_drive_host",navi.getClass().getName());runOnMainSync(()->navi.findViewById(navi.getResources().getIdentifier("search_button","id",navi.getPackageName())).performClick());Thread.sleep(1000);
  AccessibilityNodeInfo label=null;for(int attempt=0;attempt<20&&label==null;attempt++){Thread.sleep(300);label=text(getUiAutomation().getRootInActiveWindow(),"장소 검색");}check(label!=null,"Magnifier search field missing");while(label!=null&&!label.isClickable())label=label.getParent();check(label!=null,"Search entry not clickable");label.performAction(AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(1700);Activity input=current;report.put("input_host",input.getClass().getName());runOnMainSync(()->{EditText edit=input.findViewById(input.getResources().getIdentifier("search_edit_text","id",input.getPackageName()));if(edit==null)throw new RuntimeException("Native input missing");edit.setText(query);edit.onEditorAction(EditorInfo.IME_ACTION_SEARCH);});Thread.sleep(6500);Activity results=current;report.put("result_host",results.getClass().getName());JSONArray views=new JSONArray();runOnMainSync(()->{try{tree(results.getWindow().getDecorView(),views);}catch(Exception e){throw new RuntimeException(e);}});report.put("result_views",views);View[] button={null};runOnMainSync(()->button[0]=tag(results.getWindow().getDecorView(),"kisa-naver-place-search"));report.put("naver_button_exists",button[0]!=null).put("naver_button_visible",button[0]!=null&&button[0].isShown());shot("magnifier-native-results.png");check(button[0]!=null&&button[0].isShown(),"Naver additional search missing after actual magnifier search");runOnMainSync(()->button[0].performClick());Thread.sleep(1500);shot("magnifier-naver-results.png");check(text(getUiAutomation().getRootInActiveWindow(),query)!=null,"Original query not reused");report.put("query_reused",true);AccessibilityNodeInfo exact=null;for(int i=0;i<40&&exact==null;i++){exact=contains(getUiAutomation().getRootInActiveWindow(),"수학의힘 신검단캠퍼스");if(exact==null)Thread.sleep(250);}check(exact!=null,"Exact Naver branch missing after spaced query");report.put("naver_exact_branch_visible",true);
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();try{report.put("error",e.toString());shot("failure.png");}catch(Exception ignored){}}try{if(hostMode.equals("route")){Object navManager=cl.loadClass("com.skt.tmap.engine.navigation.NavigationManager").getMethod("getInstance").invoke(null);main(()->navManager.getClass().getMethod("stopDriving",boolean.class).invoke(navManager,false));}}catch(Exception ignored){}try{Files.write(new File(dir,"report.json").toPath(),report.toString(2).getBytes("UTF-8"));}catch(Exception ignored){}result.putString("report",report.toString());finish(Activity.RESULT_OK,result);}
}
